!function(t){function e(e){for(var n,i,p=e[0],m=e[1],c=e[2],s=0,g=[];s<p.length;s++)i=p[s],Object.prototype.hasOwnProperty.call(a,i)&&a[i]&&g.push(a[i][0]),a[i]=0;for(n in m)Object.prototype.hasOwnProperty.call(m,n)&&(t[n]=m[n]);for(d&&d(e);g.length;)g.shift()();return o.push.apply(o,c||[]),r()}function r(){for(var t,e=0;e<o.length;e++){for(var r,i=o[e],p=!0,m=1;m<i.length;m++)r=i[m],0!==a[r]&&(p=!1);p&&(o.splice(e--,1),t=n(n.s=i[0]))}return t}function n(e){if(i[e])return i[e].exports;var r=i[e]={i:e,l:!1,exports:{}};return t[e].call(r.exports,r,r.exports,n),r.l=!0,r.exports}var i={},a={38:0},o=[];n.m=t,n.c=i,n.d=function(t,e,r){n.o(t,e)||Object.defineProperty(t,e,{enumerable:!0,get:r})},n.r=function(t){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(t,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(t,"__esModule",{value:!0})},n.t=function(t,e){if(1&e&&(t=n(t)),8&e)return t;if(4&e&&"object"==typeof t&&t&&t.__esModule)return t;var r=Object.create(null);if(n.r(r),Object.defineProperty(r,"default",{enumerable:!0,value:t}),2&e&&"string"!=typeof t)for(var i in t)n.d(r,i,function(e){return t[e]}.bind(null,i));return r},n.n=function(t){var e=t&&t.__esModule?function(){return t.default}:function(){return t};return n.d(e,"a",e),e},n.o=function(t,e){return Object.prototype.hasOwnProperty.call(t,e)},n.p="";var p=window.webpackJsonp=window.webpackJsonp||[],m=p.push.bind(p);p.push=e,p=p.slice();for(var c=0;c<p.length;c++)e(p[c]);var d=m;o.push([32,0]),r()}({32:function(t,e,r){"use strict";r.r(e);var n=r(0);Object(n.a)("de","army",r(33),r(1))},33:function(t){t.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"坦克","link":"de_army#de_army_tank"}],"model":"35（t）坦克（捷克产）","description":"<h6>综述：</h6><p>35（t）坦克和38（t）坦克都是捷克生产的，在当是一种性能较好的轻型坦克。1939年3月，德军占领了捷克斯洛伐克，发现这二种坦克在火力和防护上都超过了当时德军的Ⅰ号和Ⅱ号坦克，同时也因为当时德国本土生产的Ⅲ号和Ⅳ号z装备数量不足，因此就要求捷克继续生产这二种坦克，而这二种坦克也就因此成为二战初期德军装甲部队的装备，参加了进攻波兰和法国的战斗，也有过出色的表现。但后来随着战争的发展，这二种坦克的装甲与火炮已完全落后，根本无法与苏军和盟军的坦克对抗，到了1942年，这二种型号的坦克就停产了，战场上余下的坦克则改作训练与非战斗用途，也有一部分被斯洛伐克和罗马利亚军队使用到战争结束。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"imgs/de/army/de_army_tank35_11.jpg","description":"<h6>35（t）坦克 Pz.Kpfw.35（t）</h6><p>35（t）该坦克于1934年由捷克研发，1935年定型（LtVz35）并开始量产，1939年德军侵占捷克后改名为Pz.Kpfw.35（t）纳入de德军现役。</p></p>该坦克车长：4.9m, 车宽：2.1m, 车高：2.35m, 车重10.7t; 乘员4人;发动机为120匹马力，最大时速：35km/h, 最大行程：190km, 涉水深度为1m；装甲厚度：正面25mm、侧面16mm、背面12mm。武器：一门37mm KwK34（t）坦克炮，二挺7.92mm MG37（t）机枪。</p>","caption":"<strong>外形特点：</strong><ol><li>悬挂系统中是4对用连杆连接的8个小型负重轮。</li><li>炮塔前部除炮管外，机枪也伸出前部。</li><li>炮塔上为圆形的舱盖。</li></ol>"},{"image":"{{text}}1939年生产的35（t） Z1型坦克{{image}}imgs/de/army/de_army_tank35_12.jpg","description":"","caption":""},{"image":"{{text}}1940年生产的35（t） Z3型坦克{{image}}imgs/de/army/de_army_tank35_13.jpg","description":"","caption":""},{"image":"{{text}}1940年生产的35（t） Z6型坦克{{image}}imgs/de/army/de_army_tank35_14.jpg","description":"","caption":""},{"image":"{{text}}1941年生产的35（t） Z7型坦克{{image}}imgs/de/army/de_army_tank35_15.jpg","description":"","caption":""}],"part2title":"战场上的35（t）坦克","part2description":"<p>侵占捷克后，德军征集了200多辆35（t）坦克，其中大部分分配给德军第6装甲师（原第一轻装师），参加了入侵波兰和法国的行动，继而又参加了入侵苏联的战斗。第6装甲师在闪击法国中，曾快速地突破了法军的防线，俘获了近1000名法军官兵。后来进入东线战场上作战，在苏联严寒的天气中，该型坦克的动力装置故障频发，严重影响了战斗发挥，而面对苏军坦克装备的加强，该型坦克薄弱的装甲，已难以在战斗中生存，只能退出了战场。</p>","part2content":[{"image":"imgs/de/army/de_army_tank35_21.jpg","description":"在法国领土上快速前进的德军第6装甲师的35（t）坦克编队。","caption":""},{"image":"imgs/de/army/de_army_tank35_22.jpg","description":"在法国闪击战中，35（t）坦克与步兵一起协同进攻，该型坦克在快速进攻中有不错的表现。","caption":""},{"image":"imgs/de/army/de_army_tank35_23.jpg","description":"在1940年6月的法国闪击战中，第6装甲师的35（t）坦克集群正在快速攻击前进。","caption":""},{"image":"imgs/de/army/de_army_tank35_24.jpg","description":"在通往列宁格勒的路上，一辆隶属德军第6装甲师的35（t）坦克准备拖动一辆陷入泥泞中的运输车辆，摩托车隶属于其第4步枪团第9连的维修部门。","caption":""},{"image":"imgs/de/army/de_army_tank35_25.jpg","description":"搭乘坦克前进的步兵在下车，前面一辆是35（t）坦克，后面是一辆Ⅳ号坦克。","caption":""},{"image":"imgs/de/army/de_army_tank35_26.jpg","description":"德军第11装甲团5连的一辆35（t）坦克，这幅图片较清楚地显示了此型坦克的特征，在37mm的坦克炮上方较粗壮的管子是炮管制退器。","caption":""}]}')}});